export const envelope = [14, 11, 16];

export default function build(api) {
  const [sizeX, sizeY, sizeZ] = api.size;
  const seatPlaneY = 3;

  function withState(blockStr, stateStr) {
    if (!blockStr) return "";
    const isSlabState = stateStr.includes("type=");
    if (isSlabState && !blockStr.includes("_slab") && !blockStr.includes("slab")) {
      return blockStr;
    }
    const bracketIdx = blockStr.indexOf("[");
    if (bracketIdx === -1) {
      return `${blockStr}[${stateStr}]`;
    }
    const base = blockStr.slice(0, bracketIdx);
    const existing = blockStr.slice(bracketIdx + 1, -1);
    const stateMap = new Map();
    if (existing.length > 0) {
      for (const part of existing.split(",")) {
        const eq = part.indexOf("=");
        if (eq !== -1) {
          stateMap.set(part.slice(0, eq).trim(), part.slice(eq + 1).trim());
        }
      }
    }
    for (const part of stateStr.split(",")) {
      const eq = part.indexOf("=");
      if (eq !== -1) {
        stateMap.set(part.slice(0, eq).trim(), part.slice(eq + 1).trim());
      }
    }
    const merged = Array.from(stateMap.entries())
      .map(([k, v]) => `${k}=${v}`)
      .join(",");
    return `${base}[${merged}]`;
  }

  function setBlock(x, y, z, block) {
    if (x >= 0 && x < sizeX && y >= 0 && y < sizeY && z >= 0 && z < sizeZ && block) {
      api.set(x, y, z, block);
    }
  }

  const theme = api.theme || {};
  const stone = theme.stone || {};
  const ground = theme.ground || {};
  const wood = theme.wood || {};

  const stonePrimary = stone.primary || "minecraft:stone_bricks";
  const stoneAccent = stone.accent || "minecraft:deepslate_bricks";
  const stoneStairs = stone.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = stone.slab || "minecraft:stone_brick_slab";
  const stoneWall = stone.wall || "minecraft:stone_brick_wall";

  const groundPavement = ground.pavement || "minecraft:cobblestone";
  const groundCoping = ground.coping || "minecraft:stone_slab";
  const groundPlinth = ground.plinth || "minecraft:deepslate_bricks";
  const groundRevetment = ground.revetment || "minecraft:stone_bricks";

  const woodPlanks = wood.planks || "minecraft:dark_oak_planks";
  const woodLog = wood.log || "minecraft:dark_oak_log";
  const woodStripped = wood.stripped || "minecraft:stripped_dark_oak_log";
  const woodSlab = wood.slab || "minecraft:dark_oak_slab";
  const woodTrapdoor = wood.trapdoor || "minecraft:dark_oak_trapdoor";

  function getMasonry(x, y, z, isWet = false) {
    const r = (Math.sin(x * 12.9898 + y * 78.233 + z * 37.719) * 43758.5453) % 1;
    const val = r < 0 ? r + 1 : r;
    if (isWet || y <= 1) {
      if (val < 0.4) return stoneAccent;
      if (val < 0.6) return "minecraft:mossy_stone_bricks";
      return stonePrimary;
    }
    if (val < 0.25) return stoneAccent;
    if (val < 0.38) return "minecraft:cracked_stone_bricks";
    return stonePrimary;
  }

  function getPavement(x, y, z) {
    const r = (Math.sin(x * 39.34 + y * 11.73 + z * 93.17) * 43758.5453) % 1;
    const val = r < 0 ? r + 1 : r;
    if (val < 0.5) return groundPavement;
    if (val < 0.75) return stonePrimary;
    if (val < 0.88) return groundPlinth;
    return "minecraft:mossy_cobblestone";
  }

  // Determine lock operation state across plugin instances
  const instIdx = (api.instance.index || 0) % 3;

  // 1. Foundation and Terrain Conformance
  for (let x = 0; x < sizeX; x++) {
    for (let z = 0; z < sizeZ; z++) {
      const h = Math.round(api.heightAt(x, z));
      const groundY = seatPlaneY + h;
      const isTowpathWest = x <= 3;
      const isTowpathEast = x >= 10;
      const isChamber = x >= 4 && x <= 9;

      if (isTowpathWest || isTowpathEast) {
        const bottomY = Math.max(0, Math.min(groundY, seatPlaneY));
        for (let y = bottomY; y <= 2; y++) {
          setBlock(x, y, z, getMasonry(x, y, z, y <= 1));
        }
        if (x <= 2 || x >= 11) {
          setBlock(x, 3, z, getPavement(x, 3, z));
        }
        if (groundY > 3) {
          const topHill = Math.min(sizeY - 1, groundY);
          for (let y = 4; y <= topHill; y++) {
            if (x === 0 || x === sizeX - 1) {
              setBlock(x, y, z, groundRevetment);
            } else {
              setBlock(x, y, z, getMasonry(x, y, z, false));
            }
          }
        }
      } else if (isChamber) {
        const bottomY = Math.max(0, Math.min(groundY, 1));
        for (let y = bottomY; y <= 0; y++) {
          setBlock(x, y, z, groundPlinth);
        }
        setBlock(x, 1, z, getMasonry(x, 1, z, true));
      }
    }
  }

  // 2. Lock Chamber Walls & Quoins
  for (let z = 0; z < sizeZ; z++) {
    // West Chamber Wall (x = 3)
    for (let y = 1; y <= 3; y++) {
      setBlock(3, y, z, getMasonry(3, y, z, y <= 1));
    }
    // East Chamber Wall (x = 10)
    for (let y = 1; y <= 3; y++) {
      setBlock(10, y, z, getMasonry(10, y, z, y <= 1));
    }

    // Wall Copings
    setBlock(3, 3, z, groundCoping);
    setBlock(10, 3, z, groundCoping);
  }

  // Gate Recesses in walls (z = 8..11)
  for (let z = 8; z <= 11; z++) {
    setBlock(3, 2, z, withState(stoneStairs, "facing=east,half=bottom"));
    setBlock(10, 2, z, withState(stoneStairs, "facing=west,half=bottom"));
  }

  // Hollow Quoins at z = 7 (Hinge pockets for heel posts)
  setBlock(3, 2, 7, withState(stoneStairs, "facing=south,half=bottom"));
  setBlock(3, 3, 7, withState(stoneStairs, "facing=south,half=bottom"));
  setBlock(10, 2, 7, withState(stoneStairs, "facing=south,half=bottom"));
  setBlock(10, 3, 7, withState(stoneStairs, "facing=south,half=bottom"));

  // 3. Mitre Sill (Cill) on Canal Floor (y = 2, pointing north / upstream)
  setBlock(6, 2, 5, stoneAccent);
  setBlock(7, 2, 5, stoneAccent);
  setBlock(5, 2, 6, stoneAccent);
  setBlock(8, 2, 6, stoneAccent);
  setBlock(4, 2, 7, stoneAccent);
  setBlock(9, 2, 7, stoneAccent);

  // Sill bumper timbers
  setBlock(6, 2, 4, withState(woodStripped, "axis=x"));
  setBlock(7, 2, 4, withState(woodStripped, "axis=x"));
  setBlock(5, 2, 5, withState(woodStripped, "axis=x"));
  setBlock(8, 2, 5, withState(woodStripped, "axis=x"));

  // 4. Lock Gates & Balance Beams per Instance
  if (instIdx === 0) {
    // === INSTANCE 0: CLOSED MITRE GATES UNDER FULL HEAD ===
    // West Gate Leaf
    for (let y = 1; y <= 5; y++) {
      setBlock(4, y, 7, withState(woodLog, "axis=y")); // Heel post
      setBlock(5, y, 6, woodPlanks);                    // Leaf
      setBlock(6, y, 5, withState(woodLog, "axis=y")); // Mitre post
    }
    // West Gate Iron straps & walkway
    setBlock(4, 3, 7, withState(woodTrapdoor, "facing=south,half=bottom"));
    setBlock(6, 3, 5, withState(woodTrapdoor, "facing=north,half=bottom"));
    setBlock(4, 5, 7, withState(woodSlab, "type=top"));
    setBlock(5, 5, 6, withState(woodSlab, "type=top"));
    setBlock(6, 5, 5, withState(woodSlab, "type=top"));
    // West Handrail
    setBlock(4, 6, 7, "minecraft:iron_bars");
    setBlock(5, 6, 6, "minecraft:iron_bars");
    setBlock(6, 6, 5, "minecraft:iron_bars");

    // West Balance Beam (extending back across towpath)
    setBlock(3, 5, 7, withState(woodLog, "axis=x"));
    setBlock(2, 5, 8, withState(woodLog, "axis=z"));
    setBlock(1, 4, 9, withState(woodLog, "axis=z"));
    setBlock(0, 4, 10, "minecraft:anvil[facing=north]"); // Counterbalance weight
    setBlock(0, 3, 10, groundPlinth);

    // West Paddle Gear (Rack & Pinion Sluice)
    setBlock(5, 6, 6, "minecraft:hopper[facing=down]");
    setBlock(5, 7, 6, "minecraft:lightning_rod[facing=up]");
    setBlock(5, 6, 5, "minecraft:lever[face=wall,facing=north]");

    // East Gate Leaf
    for (let y = 1; y <= 5; y++) {
      setBlock(9, y, 7, withState(woodLog, "axis=y")); // Heel post
      setBlock(8, y, 6, woodPlanks);                    // Leaf
